/**
 * Generates src/data/toolshop.ts from the delivered dashboard data.
 *
 * The source of truth is D:\Tool shop\06 Dashboard\data\, which is itself
 * generated by _tools/generate_test_summary_reports.js from the delivered
 * workbooks and reports. Nothing here is hand-entered, so no figure on the
 * site can drift from what was actually delivered.
 *
 * Run: node scripts/generate-toolshop-data.mjs
 * Override the source with TOOLSHOP_DATA_DIR.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const DATA_DIR =
  process.env.TOOLSHOP_DATA_DIR ?? 'D:\\Tool shop\\06 Dashboard\\data';
const OUT = join(HERE, '..', 'src', 'data', 'toolshop.ts');

const read = (name) => JSON.parse(readFileSync(join(DATA_DIR, name), 'utf8'));

const meta = read('meta.json');
const crossModule = read('cross-module.json');
const stories = meta.index.map((entry) => read(entry.file));

// --- derive the roll-ups the site shows, rather than trusting a second copy ---
const sum = (pick) => stories.reduce((acc, s) => acc + pick(s), 0);

const severityRollup = (pick) => ({
  total: sum((s) => pick(s).total),
  high: sum((s) => pick(s).high),
  medium: sum((s) => pick(s).medium),
  low: sum((s) => pick(s).low),
  unrated: sum((s) => pick(s).unrated),
});

const defectSeverity = severityRollup((s) => s.defects);
const staticSeverity = severityRollup((s) => s.staticFindings);
const areaCount = sum((s) => s.areas.length);

// Failures that were executed but never written up as a defect report.
const failuresAwaitingWriteUp = stories
  .filter((s) => s.defects.total === 0 && s.cases.failed > 0)
  .reduce((acc, s) => acc + s.cases.failed, 0);

// --- consistency gates: refuse to emit a file that disagrees with meta.json ---
const checks = [
  ['cases', sum((s) => s.cases.written), meta.totals.cases],
  ['executed', sum((s) => s.cases.executed), meta.totals.executed],
  ['passed', sum((s) => s.cases.passed), meta.totals.passed],
  ['failed', sum((s) => s.cases.failed), meta.totals.failed],
  ['blocked', sum((s) => s.cases.blocked), meta.totals.blocked],
  ['notRun', sum((s) => s.cases.notRun), meta.totals.notRun],
  ['defectsLogged', defectSeverity.total, meta.totals.defectsLogged],
  ['staticFindings', staticSeverity.total, meta.totals.staticFindings],
  ['failuresAwaitingWriteUp', failuresAwaitingWriteUp, meta.totals.failuresAwaitingWriteUp],
  ['stories', stories.length, meta.totals.stories],
];

const mismatches = checks.filter(([, derived, declared]) => derived !== declared);
if (mismatches.length) {
  for (const [name, derived, declared] of mismatches) {
    console.error(`  MISMATCH ${name}: derived ${derived} vs meta.json ${declared}`);
  }
  throw new Error('Derived totals disagree with meta.json - refusing to generate.');
}

const banner = `// GENERATED FILE - DO NOT EDIT BY HAND.
//
// Source: ${DATA_DIR}
// Generated by scripts/generate-toolshop-data.mjs on ${new Date().toISOString()}
//
// Every figure the site displays originates here. To change a number, fix the
// delivered workbook, re-run the dashboard generator, then re-run this script.
`;

const body = `${banner}
export interface CaseCounts {
  written: number;
  executed: number;
  passed: number;
  failed: number;
  blocked: number;
  notRun: number;
  /** Null when nothing was executed, so "no result" never renders as 0%. */
  passRate: number | null;
  execRate: number;
}

export interface PriorityCounts {
  high: number;
  medium: number;
  low: number;
  unset: number;
}

/** Counts by severity. \`unrated\` is kept separate - it is not Low. */
export interface SeverityCounts {
  total: number;
  high: number;
  medium: number;
  low: number;
  unrated: number;
}

export interface TestArea {
  name: string;
  total: number;
  passed: number;
  failed: number;
  blocked: number;
  notRun: number;
}

export interface ModuleArtifacts {
  story: boolean;
  cases: boolean;
  static: boolean;
  bugReport: boolean;
  delivered: number;
  of: number;
}

export interface CrossModuleRefs {
  integration: { total: number; passed: number; failed: number };
  e2e: { total: number; passed: number; blocked: number };
}

export type ModuleState = ${[...new Set(stories.map((s) => s.state))]
  .sort()
  .map((s) => `'${s}'`)
  .join(' | ')};

export interface ModuleStory {
  id: string;
  module: string;
  shortName: string;
  owner: string;
  state: ModuleState;
  stateLabel: string;
  artifacts: ModuleArtifacts;
  cases: CaseCounts;
  priority: PriorityCounts;
  areas: TestArea[];
  defects: SeverityCounts;
  staticFindings: SeverityCounts;
  crossModule: CrossModuleRefs;
}

export interface ProjectTotals {
  stories: number;
  storiesWithCases: number;
  storiesComplete: number;
  cases: number;
  executed: number;
  passed: number;
  failed: number;
  blocked: number;
  notRun: number;
  passRate: number;
  execRate: number;
  defectsLogged: number;
  failuresAwaitingWriteUp: number;
  staticFindings: number;
}

export const projectName = ${JSON.stringify(meta.project)};
export const teamName = ${JSON.stringify(meta.team)};
export const applicationUnderTest = ${JSON.stringify(meta.applicationUnderTest)};
export const appUrl = ${JSON.stringify(meta.appUrl)};
export const reportDate = ${JSON.stringify(meta.reportDate)};

export const totals: ProjectTotals = ${JSON.stringify(meta.totals, null, 2)};

/** Severity split of the ${defectSeverity.total} logged defects. */
export const defectSeverity: SeverityCounts = ${JSON.stringify(defectSeverity, null, 2)};

/** Severity split of the ${staticSeverity.total} static review findings. */
export const staticSeverity: SeverityCounts = ${JSON.stringify(staticSeverity, null, 2)};

/** Number of distinct test areas across all modules. */
export const areaCount = ${areaCount};

export const crossModule = ${JSON.stringify(crossModule, null, 2)};

export const moduleStories: ModuleStory[] = ${JSON.stringify(stories, null, 2)};
`;

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, body, 'utf8');

console.log(`Wrote ${OUT}`);
console.log(
  `  ${stories.length} modules, ${areaCount} test areas, ` +
    `${meta.totals.cases} cases, ${defectSeverity.total} defects, ` +
    `${staticSeverity.total} static findings`
);
console.log('  all derived totals agree with meta.json');
